-- Фаза 8 «Безпека»: кошик клієнтів (Джері не видаляє назавжди)
ALTER TABLE clients ADD COLUMN deleted_at TEXT;

INSERT INTO changelog (title, body, created_at) VALUES ('Безпека: вхід через Telegram, 7 днів, кошик', 'Що змінилось:
- Вхід: після пароля Джері пише тобі в Telegram «Це ти?» з кнопками ✅ / ⛔ — без «Це я» не пустить (5 хв на підтвердження). Якщо Telegram недоступний — пускає паролем і пише в журнал. Вимкнути можна в Налаштування → Доступи → «Вхід».
- «Запамʼятати пристрій» — тепер 7 днів (було 30). Після оновлення доведеться один раз увійти заново.
- «Вийти на всіх пристроях» — Налаштування → Доступи. Усі сесії (і цей пристрій) виходять.
- Ключ доступу для Claude має термін 90 днів (видно, до якого числа). Потім — згенерувати новий.
- Посилання «Звіт для клієнта» (/r/…) діє 90 днів від увімкнення / «Нове посилання»; запасного ключа більше нема.
- Джері більше не видаляє клієнтів назавжди: «видали» = кошик на 30 днів (Клієнти → Архів → «Повернути»).
- Паролі в Telegram-групах: якщо хтось написав «пароль: …», у базі воно замасковане (••••••), а тобі приходить нагадування перенести в Bitwarden і Доступи. Те саме при імпорті старої історії.
- Бекапи: правдиві підписи (на сервері 03:30 за Києвом, 14 шт.; на Google Диску 04:00, 30 шт.; перед оновленням з міграціями — ще копія). Раз на місяць система сама перевіряє, що копія відкривається; не ок — повідомлення в Telegram.
- Памʼять Джері більше не обрізається мовчки: на 90% він отримує команду стиснути, при переповненні — помилку, а не тиху втрату нових нотаток.', datetime('now'));
